fn sort_ascending(v: Vec<Int>) -> Vec<Int> {
    let mut sorted = v;
    let len = len(&sorted);
    for i in 0..len {
        for j in 0..len - i - 1 {
            if sorted[j] > sorted[j + 1] {
                let temp = sorted[j];
                sorted[j] = sorted[j + 1];
                sorted[j + 1] = temp;
            }
        }
    }
    sorted
}

