struct Rect { width: Int, height: Int }
struct Tri { a: Int, b: Int, c: Int }

fn perimeter_of_rect(r: Rect) -> Int {
    2 * (r.width + r.height)
}

fn perimeter_of_tri(t: Tri) -> Int {
    t.a + t.b + t.c
}

fn main() {
    let r1 = Rect { width: 3, height: 4 };
    let t1 = Tri { a: 3, b: 4, c: 5 };
    let r2 = Rect { width: 2, height: 5 };

    print(perimeter_of_rect(r1));
    print(perimeter_of_tri(t1));
    print(perimeter_of_rect(r2));
}

